export const DINO_FALLBACK_HTML = "<!DOCTYPE html>\n<html lang=\"fr\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, maximum-scale=1, user-scalable=no, viewport-fit=cover\">\n<title>DINO CORRIDOR</title>\n<style>\n  /* ==========================================================\n     DINO CORRIDOR — design tokens\n     Rétro-horreur VHS / arcade 80-90 — noir quasi absolu,\n     accent unique brûlé, beige chaud. Finition sobre et lisible.\n     ========================================================== */\n  :root{\n    --void:        #060504;\n    --void-2:      #0b0906;\n    --panel:       #120e0a;\n    --panel-2:     #17120c;\n    --line:        rgba(232,220,200,0.10);\n    --line-strong: rgba(232,220,200,0.22);\n    --cream:       #ecdfc7;\n    --cream-dim:   #a89a80;\n    --cream-faint: #6e6350;\n    --ember:       #d9552d;\n    --ember-hi:    #ef7248;\n    --ember-dim:   #7a3320;\n    --ember-deep:  #3a1a10;\n    --ember-glow:  rgba(217,85,45,0.45);\n    --ok:          #6fae6b;\n    --r-s:  4px;\n    --r-m:  8px;\n    --r-l:  14px;\n    --ease: cubic-bezier(.22,.8,.28,1);\n    --font: ui-monospace, 'SF Mono', 'Cascadia Mono', 'JetBrains Mono', Consolas, 'Courier New', monospace;\n    --safe-t: env(safe-area-inset-top, 0px);\n    --safe-b: env(safe-area-inset-bottom, 0px);\n    --safe-l: env(safe-area-inset-left, 0px);\n    --safe-r: env(safe-area-inset-right, 0px);\n  }\n  @media (prefers-color-scheme: dark){ :root:not([data-theme=\"light\"]){ color-scheme: dark; } }\n  :root[data-theme=\"dark\"]{ color-scheme: dark; }\n\n  *{ box-sizing: border-box; -webkit-tap-highlight-color: transparent; }\n  html, body{\n    margin:0; padding:0; width:100%; height:100%;\n    overflow:hidden; background: var(--void);\n    touch-action:none; user-select:none; -webkit-user-select:none;\n    font-family: var(--font);\n    color: var(--cream);\n    -webkit-font-smoothing: antialiased;\n  }\n  canvas{ display:block; background: var(--void); }\n  ::selection{ background: var(--ember-dim); color: var(--cream); }\n\n  /* grain + scanlines + vignette — discret, purement atmosphérique */\n  body::before{\n    content:''; position:fixed; inset:0; z-index:3; pointer-events:none;\n    background-image: repeating-linear-gradient(rgba(255,255,255,0.03) 0 1px, transparent 1px 3px);\n    mix-blend-mode: overlay;\n    opacity:0.4;\n  }\n  body::after{\n    content:''; position:fixed; inset:0; z-index:3; pointer-events:none;\n    background: radial-gradient(ellipse at 50% 45%, rgba(0,0,0,0) 42%, rgba(0,0,0,0.55) 100%);\n  }\n\n  .hidden{ display:none !important; }\n  button{ font-family: inherit; }\n  input{ font-family: inherit; }\n  h1,h2,p{ margin:0; }\n\n  /* ---------------- HUD ---------------- */\n  #hud{\n    position:fixed; top:0; left:0; right:0; z-index:5;\n    display:flex; justify-content:space-between; align-items:flex-start;\n    gap:8px;\n    padding: calc(var(--safe-t) + 10px) calc(var(--safe-r) + 10px) 0 calc(var(--safe-l) + 10px);\n    pointer-events:none;\n  }\n  .hud-panel{\n    background: rgba(9,7,5,0.72);\n    backdrop-filter: blur(8px) saturate(1.15);\n    -webkit-backdrop-filter: blur(8px) saturate(1.15);\n    border: 1px solid var(--line);\n    border-radius: var(--r-m);\n    padding: 7px 11px;\n    min-width: 128px;\n    box-shadow: 0 4px 16px rgba(0,0,0,0.4);\n  }\n  .hud-panel--score{ text-align:right; }\n\n  .hud-vitals{ display:flex; align-items:center; gap:8px; }\n  .hud-vitals__label{\n    font-size:9px; font-weight:700; letter-spacing:1.5px; color: var(--ember-hi);\n    flex-shrink:0;\n  }\n  .hud-vitals__track{\n    width:88px; height:6px; border-radius:3px; background: var(--void-2);\n    border:1px solid var(--ember-deep); overflow:hidden;\n  }\n  .hud-vitals__fill{\n    height:100%; width:100%; border-radius:2px;\n    background: linear-gradient(90deg, var(--ember-dim), var(--ember) 65%, var(--ember-hi));\n    transition: width 0.2s ease-out;\n  }\n  #weaponLabel{\n    display:flex; align-items:center; gap:5px; margin-top:7px;\n    font-size:10px; letter-spacing:0.6px; color: var(--cream-dim);\n    padding:3px 0 0; border-top:1px solid var(--line);\n  }\n\n  .hud-stat{ display:flex; justify-content:flex-end; align-items:baseline; gap:7px; line-height:1.45; }\n  .hud-stat__label{ font-size:9px; letter-spacing:1.5px; color: var(--cream-faint); }\n  .hud-stat__value{ font-size:14px; font-weight:700; color: var(--cream); min-width:1.4em; text-align:right; }\n  .hud-mp{ display:block; margin-top:4px; font-size:9.5px; color:#8ecae6; letter-spacing:0.2px; }\n\n  /* ---------------- damage / vignette / crosshair ---------------- */\n  #damageFlash{\n    position:fixed; inset:0; z-index:8; pointer-events:none;\n    background: radial-gradient(ellipse at center, rgba(160,0,0,0) 35%, rgba(160,20,10,0.6) 100%);\n    opacity:0; transition: opacity 0.4s ease-out;\n  }\n  #damageFlash.active{ opacity:1; transition: opacity 0.03s; }\n  #lowHealthVignette{\n    position:fixed; inset:0; z-index:7; pointer-events:none;\n    background: radial-gradient(ellipse at center, rgba(120,0,0,0) 45%, rgba(120,10,5,0.5) 100%);\n    opacity:0; transition: opacity 0.6s ease;\n  }\n\n  #crosshair{\n    position:fixed; top:50%; left:50%; transform: translate(-50%,-50%);\n    width:22px; height:22px; pointer-events:none; z-index:5;\n    border:1px solid rgba(236,223,199,0.5); border-radius:50%;\n    transition: border-color 0.1s ease;\n  }\n  #crosshair::before, #crosshair::after{ content:''; position:absolute; background: rgba(236,223,199,0.8); }\n  #crosshair::before{ top:50%; left:8px; right:8px; height:1.5px; transform: translateY(-50%); }\n  #crosshair::after{ left:50%; top:8px; bottom:8px; width:1.5px; transform: translateX(-50%); }\n  #crosshair.hit{ border-color: var(--ember-hi); transform: translate(-50%,-50%) scale(1.15); }\n  #crosshair.hit::before, #crosshair.hit::after{ background: var(--ember-hi); }\n\n  /* ---------------- touch controls ---------------- */\n  .stick-base{\n    position:fixed; border-radius:50%; z-index:6;\n    background: rgba(15,11,8,0.42);\n    border:1px solid var(--line-strong);\n    box-shadow: inset 0 0 18px rgba(0,0,0,0.5), 0 6px 16px rgba(0,0,0,0.4);\n  }\n  .stick-nub{\n    position:absolute; border-radius:50%; top:50%; left:50%; transform: translate(-50%,-50%);\n    background: radial-gradient(circle at 35% 30%, var(--ember) 0%, var(--ember-dim) 72%);\n    border:1px solid rgba(236,223,199,0.35);\n    box-shadow: 0 3px 10px rgba(0,0,0,0.5);\n  }\n  #fireBtn{\n    position:fixed; border-radius:50%; z-index:6;\n    background: radial-gradient(circle at 35% 30%, rgba(217,85,45,0.34), rgba(90,40,25,0.26));\n    border:2px solid var(--ember);\n    color: var(--cream); font-size:11px; font-weight:700; letter-spacing:1px;\n    display:flex; align-items:center; justify-content:center;\n    box-shadow: inset 0 0 16px rgba(0,0,0,0.35);\n    transition: transform 0.08s ease, box-shadow 0.15s ease, background 0.15s ease;\n  }\n  #fireBtn.pressed{\n    background: radial-gradient(circle at 35% 30%, rgba(217,85,45,0.88), rgba(90,40,25,0.6));\n    box-shadow: 0 0 20px var(--ember-glow), inset 0 0 16px rgba(0,0,0,0.35);\n    transform: scale(0.94);\n  }\n  #desktopHint{\n    position:fixed; left:50%; transform: translateX(-50%); z-index:6;\n    bottom: calc(var(--safe-b) + 14px);\n    background: rgba(9,7,5,0.7);\n    border:1px solid var(--line); border-radius: var(--r-s);\n    color: var(--cream-dim); font-size:11px; letter-spacing:0.3px;\n    padding:7px 15px; white-space:nowrap; pointer-events:none;\n  }\n\n  /* ---------------- rotate prompt ---------------- */\n  #rotatePrompt{\n    display:none; position:fixed; inset:0; z-index:50;\n    background: var(--void); color: var(--cream); text-align:center;\n    flex-direction:column; align-items:center; justify-content:center;\n    padding:24px; gap:16px;\n  }\n  .rotate-prompt__icon{ font-size:40px; animation: rp-spin 1.8s ease-in-out infinite; filter: drop-shadow(0 0 10px var(--ember-glow)); }\n  #rotatePrompt p{ font-size:13px; color: var(--cream-dim); max-width:260px; line-height:1.6; }\n  @keyframes rp-spin{ 0%,100%{ transform: rotate(0deg); } 50%{ transform: rotate(-90deg); } }\n  @media (orientation: landscape) and (pointer: coarse) and (max-height: 500px) {\n    #rotatePrompt{ display:flex; }\n    #hud, #crosshair, .stick-base, #fireBtn, #overlay{ display:none !important; }\n  }\n\n  /* ==========================================================\n     OVERLAY / MENU\n     ========================================================== */\n  #overlay{\n    position:fixed; inset:0; z-index:10;\n    background:\n      radial-gradient(ellipse 900px 560px at 50% 8%, rgba(217,85,45,0.10), transparent 62%),\n      var(--void);\n    display:flex; align-items:center; justify-content:center;\n    padding:\n      calc(var(--safe-t) + 26px)\n      calc(var(--safe-r) + 20px)\n      calc(var(--safe-b) + 20px)\n      calc(var(--safe-l) + 20px);\n    overflow-y:auto;\n  }\n  .overlay__content{\n    width:100%; max-width:400px;\n    display:flex; flex-direction:column; align-items:stretch;\n  }\n\n  /* --- entrée orchestrée : une seule séquence, éléments enchaînés --- */\n  .brand, .divider, .controls-panel, .profile-stats, .level-select, .mode-buttons, #mpUnavailableMsg, #onlineForm, .post-game{\n    opacity:0; animation: rise 0.5s var(--ease) forwards;\n  }\n  .brand{ animation-delay: 0.02s; }\n  .divider--top{ animation-delay: 0.10s; }\n  .controls-panel{ animation-delay: 0.14s; }\n  .profile-stats{ animation-delay: 0.19s; }\n  .divider--bottom{ animation-delay: 0.22s; }\n  .level-select{ animation-delay: 0.25s; }\n  .mode-buttons{ animation-delay: 0.32s; }\n  .post-game{ animation-delay: 0.05s; }\n  @keyframes rise{ from{ opacity:0; transform: translateY(8px); } to{ opacity:1; transform: translateY(0); } }\n  @media (prefers-reduced-motion: reduce){\n    .brand, .divider, .controls-panel, .profile-stats, .level-select, .mode-buttons, #mpUnavailableMsg, #onlineForm, .post-game{ animation: none; opacity:1; }\n    .rotate-prompt__icon{ animation: none; }\n    *{ transition-duration: 0.01ms !important; }\n  }\n\n  /* --- logo / titre --- */\n  .brand{ text-align:center; margin-bottom:20px; }\n  .brand__eyebrow{\n    margin:0 0 8px; font-size:10px; letter-spacing:5px; color: var(--ember-hi);\n    font-weight:700;\n  }\n  .brand__title{\n    font-size: clamp(30px, 9vw, 42px); line-height:1;\n    letter-spacing:2px; font-weight:700; color: var(--cream);\n    text-shadow: 0 0 22px var(--ember-glow);\n  }\n  .brand__lede{\n    margin: 12px auto 0; max-width:280px;\n    font-size:12.5px; line-height:1.6; color: var(--cream-dim);\n  }\n\n  .mode-select{ width:100%; display:flex; flex-direction:column; align-items:stretch; }\n\n  /* --- séparateurs --- */\n  .divider{\n    width:100%; display:flex; align-items:center; gap:10px;\n    margin: 16px 0; color: var(--cream-faint);\n  }\n  .divider::before, .divider::after{ content:''; flex:1; height:1px; background: var(--line); }\n  .divider span{ font-size:9.5px; letter-spacing:2.5px; flex-shrink:0; }\n\n  /* --- panneau contrôles --- */\n  .controls-panel{\n    width:100%; background: var(--panel);\n    border:1px solid var(--line); border-radius: var(--r-m);\n    padding:4px 14px;\n    box-shadow: 0 8px 20px rgba(0,0,0,0.35);\n  }\n  .controls-panel__row{\n    display:flex; align-items:center; gap:11px;\n    font-size:12px; color: var(--cream-dim); text-align:left;\n    padding:9px 0;\n  }\n  .controls-panel__row + .controls-panel__row{ border-top:1px solid var(--line); }\n  .controls-panel__icon{\n    font-size:13px; width:26px; height:26px; flex-shrink:0;\n    display:flex; align-items:center; justify-content:center;\n    background: var(--void-2); border:1px solid var(--line-strong); border-radius: var(--r-s);\n  }\n\n  /* --- chip profil --- */\n  .profile-stats{\n    width:100%; margin: 14px 0 0; padding:8px 12px;\n    font-size:10.5px; color: var(--cream-dim); letter-spacing:0.2px;\n    background: rgba(236,223,199,0.03);\n    border:1px dashed var(--line-strong); border-radius: var(--r-s);\n    line-height:1.5; text-align:center;\n  }\n\n  /* --- sélection de niveau --- */\n  .level-select{ width:100%; }\n  .section-label{\n    font-size:10px; letter-spacing:2.5px; color: var(--cream-faint);\n    margin:0 0 10px; text-align:left;\n  }\n  .level-buttons{ display:grid; grid-template-columns: repeat(3, 1fr); gap:8px; width:100%; }\n\n  .levelBtn{\n    position:relative; margin:0; padding:0; overflow:hidden;\n    background: var(--panel); border:1px solid var(--line);\n    border-radius: var(--r-m); color: var(--cream-dim);\n    font-family: inherit; cursor:pointer;\n    display:flex; flex-direction:column; align-items:center;\n    transition: transform 0.15s var(--ease), border-color 0.15s ease, background 0.15s ease, box-shadow 0.15s ease;\n  }\n  .levelBtn__top{\n    width:100%; padding:16px 4px 10px; display:flex; flex-direction:column; align-items:center; gap:8px;\n  }\n  .levelBtn__icon{\n    font-size:21px; line-height:1; filter: grayscale(0.2);\n    width:42px; height:42px; display:flex; align-items:center; justify-content:center;\n    border-radius:50%; background: var(--void-2); border:1px solid var(--line-strong);\n    transition: border-color 0.15s ease, background 0.15s ease;\n  }\n  .levelBtn__name{ font-size:11px; letter-spacing:0.6px; color: var(--cream); font-weight:700; }\n  .levelBtn__diff{\n    width:100%; font-size:8px; letter-spacing:1.6px; color: var(--cream-faint); text-transform:uppercase;\n    padding:5px 4px; text-align:center; border-top:1px solid var(--line);\n    transition: color 0.15s ease, border-color 0.15s ease;\n  }\n  .levelBtn:hover{ border-color: var(--line-strong); transform: translateY(-2px); }\n  .levelBtn:hover .levelBtn__icon{ border-color: var(--ember-dim); }\n  .levelBtn:active{ transform: translateY(0) scale(0.97); }\n  .levelBtn.selected{\n    border-color: var(--ember);\n    box-shadow: 0 0 0 1px var(--ember-dim), 0 10px 22px rgba(217,85,45,0.16);\n  }\n  .levelBtn.selected::before{\n    content:''; position:absolute; top:0; left:0; right:0; height:2px;\n    background: linear-gradient(90deg, var(--ember-dim), var(--ember-hi));\n  }\n  .levelBtn.selected .levelBtn__icon{ border-color: var(--ember); background: var(--ember-deep); }\n  .levelBtn.selected .levelBtn__diff{ color: var(--ember-hi); border-color: var(--ember-dim); }\n  .levelBtn:focus-visible{ outline:2px solid var(--ember); outline-offset:2px; }\n  @media (max-width: 340px){\n    .level-buttons{ grid-template-columns: 1fr; }\n    .levelBtn{ flex-direction:row; }\n    .levelBtn__top{ flex-direction:row; justify-content:flex-start; padding:10px 12px; gap:12px; }\n    .levelBtn__diff{ width:auto; border-top:none; margin-left:auto; padding:0; }\n  }\n\n  /* ---------------- buttons ---------------- */\n  .mode-buttons{ display:flex; gap:10px; width:100%; margin-top:18px; }\n  .btn{\n    margin:0; border:none; cursor:pointer; border-radius: var(--r-m);\n    font-family: inherit; font-size:12.5px; font-weight:700; letter-spacing:1.4px;\n    padding:14px 16px; min-height:50px;\n    display:inline-flex; align-items:center; justify-content:center; gap:8px;\n    transition: transform 0.08s ease, box-shadow 0.15s ease, background 0.15s ease, opacity 0.15s ease, border-color 0.15s ease;\n  }\n  .btn:active{ transform: translateY(1px) scale(0.98); }\n  .btn:focus-visible{ outline:2px solid var(--cream); outline-offset:2px; }\n  .btn__icon{ font-size:11px; }\n\n  .btn--primary{\n    flex:1; color: #100a06;\n    background: linear-gradient(180deg, var(--ember-hi), var(--ember-dim));\n    box-shadow: 0 6px 18px rgba(217,85,45,0.28), inset 0 1px 0 rgba(255,255,255,0.15);\n  }\n  .btn--primary:hover{ box-shadow: 0 8px 22px rgba(217,85,45,0.4), inset 0 1px 0 rgba(255,255,255,0.15); }\n\n  .btn--outline{\n    flex:1; color: var(--cream);\n    background: rgba(236,223,199,0.03);\n    border:1px solid var(--line-strong);\n  }\n  .btn--outline:hover{ background: rgba(236,223,199,0.07); border-color: var(--cream-dim); }\n  .btn--outline.disabled{ opacity:0.35; cursor:not-allowed; }\n  .btn--outline.disabled:hover{ background: rgba(236,223,199,0.03); border-color: var(--line-strong); }\n\n  .btn--text{\n    background:none; color: var(--cream-faint); text-decoration:underline; text-underline-offset:2px;\n    font-weight:400; letter-spacing:0.4px; padding:8px; min-height:auto; box-shadow:none;\n  }\n  .btn--text:hover{ color: var(--cream-dim); }\n\n  .btn--large{ width:100%; padding:16px; font-size:13.5px; }\n\n  .btn--icon{ min-height:50px; width:50px; padding:0; flex:none; background: var(--panel-2); border:1px solid var(--line-strong); color:var(--cream); font-size:16px; }\n  .btn--icon:hover{ border-color: var(--ember-dim); }\n\n  .btn:disabled{ opacity:0.5; cursor:not-allowed; transform:none; }\n\n  /* ---------------- online form ---------------- */\n  .notice{ width:100%; margin-top:14px; padding:10px 12px; border-radius: var(--r-s); font-size:11px; line-height:1.6; text-align:left; }\n  .notice--warn{ color:#f0c39a; background: rgba(212,58,42,0.08); border:1px solid rgba(212,58,42,0.3); }\n\n  .online-form{ width:100%; margin-top:14px; display:flex; flex-direction:column; gap:9px; }\n  .field{ display:flex; flex-direction:column; gap:5px; text-align:left; }\n  .field--grow{ flex:1; }\n  .field__label{ font-size:9px; letter-spacing:1.6px; color: var(--cream-faint); }\n  .online-form input{\n    background: var(--panel-2); border:1px solid var(--line-strong); color: var(--cream);\n    padding:12px; font-family: inherit; font-size:13.5px; letter-spacing:1.4px;\n    text-transform:uppercase; text-align:center; border-radius: var(--r-s);\n  }\n  .online-form input:focus{ outline:none; border-color: var(--ember); box-shadow: 0 0 0 3px rgba(217,85,45,0.14); }\n  .room-row{ display:flex; gap:8px; align-items:flex-end; }\n  .mp-note{ font-size:10px; color: var(--cream-faint); line-height:1.6; text-align:left; display:block; margin-top:2px; }\n\n  .post-game{ width:100%; display:flex; flex-direction:column; align-items:center; gap:9px; margin-top:20px; }\n\n  @media (max-height: 620px){\n    .brand{ margin-bottom:12px; }\n    .brand__lede{ display:none; }\n    .divider{ margin:12px 0; }\n    .mode-buttons{ margin-top:14px; }\n  }\n\n  @media (min-width: 720px){\n    .overlay__content{ max-width:460px; }\n    .brand__title{ font-size:46px; }\n    .levelBtn__top{ padding:20px 4px 12px; }\n    .levelBtn__icon{ width:46px; height:46px; font-size:23px; }\n  }\n</style>\n</head>\n<body>\n\n<canvas id=\"game\"></canvas>\n\n<div id=\"rotatePrompt\">\n  <div class=\"rotate-prompt__icon\">📱</div>\n  <p>DINO CORRIDOR se joue en position verticale.<br>Tourne ton téléphone pour continuer.</p>\n</div>\n\n<div id=\"damageFlash\"></div>\n<div id=\"lowHealthVignette\"></div>\n\n<div id=\"hud\">\n  <div class=\"hud-panel\">\n    <div class=\"hud-vitals\">\n      <span id=\"healthLabel\" class=\"hud-vitals__label\">VIE</span>\n      <div id=\"healthBarWrap\" class=\"hud-vitals__track\"><div id=\"healthBar\" class=\"hud-vitals__fill\"></div></div>\n    </div>\n    <span id=\"weaponLabel\">🔫 PISTOLET</span>\n  </div>\n  <div class=\"hud-panel hud-panel--score\" id=\"scoreBlock\">\n    <div class=\"hud-stat\"><span class=\"hud-stat__label\">SCORE</span><span class=\"hud-stat__value\" id=\"score\">0</span></div>\n    <div class=\"hud-stat\"><span class=\"hud-stat__label\">DINOS</span><span class=\"hud-stat__value\" id=\"enemiesLeft\">0</span></div>\n    <span id=\"mpStatus\" class=\"hud-mp\"></span>\n  </div>\n</div>\n\n<div id=\"crosshair\"></div>\n\n<div id=\"overlay\">\n  <div class=\"overlay__content\">\n    <header class=\"brand\">\n      <p class=\"brand__eyebrow\">RAYCAST SURVIVAL</p>\n      <h1 id=\"ovTitle\" class=\"brand__title\">DINO CORRIDOR</h1>\n      <p id=\"ovText\" class=\"brand__lede\">Des dinosaures rôdent dans les couloirs.</p>\n    </header>\n\n    <div id=\"modeSelect\" class=\"mode-select\">\n      <div class=\"divider divider--top\"><span>CONTRÔLES</span></div>\n\n      <section class=\"controls-panel\" aria-label=\"Contrôles\">\n        <div class=\"controls-panel__row\"><span class=\"controls-panel__icon\">🕹️</span><span>Joystick gauche — se déplacer</span></div>\n        <div class=\"controls-panel__row\"><span class=\"controls-panel__icon\">🎯</span><span>Joystick droit — regarder / viser</span></div>\n        <div class=\"controls-panel__row\"><span class=\"controls-panel__icon\">🔥</span><span>Bouton rouge — tirer</span></div>\n      </section>\n\n      <p id=\"profileStats\" class=\"profile-stats\">Chargement du profil…</p>\n\n      <div class=\"divider divider--bottom\"><span>NIVEAU</span></div>\n\n      <section class=\"level-select\" aria-label=\"Sélection du niveau\">\n        <div class=\"level-buttons\">\n          <button class=\"levelBtn selected\" data-level=\"0\">\n            <span class=\"levelBtn__top\">\n              <span class=\"levelBtn__icon\">🏚️</span>\n              <span class=\"levelBtn__name\">Couloirs</span>\n            </span>\n            <span class=\"levelBtn__diff\">Facile</span>\n          </button>\n          <button class=\"levelBtn\" data-level=\"1\">\n            <span class=\"levelBtn__top\">\n              <span class=\"levelBtn__icon\">🕯️</span>\n              <span class=\"levelBtn__name\">Grotte</span>\n            </span>\n            <span class=\"levelBtn__diff\">Moyen</span>\n          </button>\n          <button class=\"levelBtn\" data-level=\"2\">\n            <span class=\"levelBtn__top\">\n              <span class=\"levelBtn__icon\">🌲</span>\n              <span class=\"levelBtn__name\">Forêt</span>\n            </span>\n            <span class=\"levelBtn__diff\">Difficile</span>\n          </button>\n          <button class=\"levelBtn\" data-level=\"3\">\n            <span class=\"levelBtn__top\">\n              <span class=\"levelBtn__icon\">🏜️</span>\n              <span class=\"levelBtn__name\">Désert</span>\n            </span>\n            <span class=\"levelBtn__diff\">Très difficile</span>\n          </button>\n          <button class=\"levelBtn\" data-level=\"4\">\n            <span class=\"levelBtn__top\">\n              <span class=\"levelBtn__icon\">🌴</span>\n              <span class=\"levelBtn__name\">Jungle</span>\n            </span>\n            <span class=\"levelBtn__diff\">Extrême</span>\n          </button>\n          <button class=\"levelBtn\" data-level=\"5\">\n            <span class=\"levelBtn__top\">\n              <span class=\"levelBtn__icon\">🌋</span>\n              <span class=\"levelBtn__name\">Lave</span>\n            </span>\n            <span class=\"levelBtn__diff\">Cauchemar</span>\n          </button>\n        </div>\n      </section>\n\n      <div class=\"mode-buttons\">\n        <button id=\"soloBtn\" class=\"btn btn--primary\"><span class=\"btn__icon\">▶</span>SOLO</button>\n        <button id=\"onlineBtn\" class=\"btn btn--outline\"><span class=\"btn__icon\">🌐</span>EN LIGNE</button>\n      </div>\n\n      <p id=\"mpUnavailableMsg\" class=\"hidden notice notice--warn\">Multijoueur indisponible dans ce navigateur — ouvre le jeu depuis l'aperçu Claude.</p>\n\n      <div id=\"onlineForm\" class=\"hidden online-form\">\n        <label class=\"field\">\n          <span class=\"field__label\">PSEUDO</span>\n          <input id=\"nickInput\" maxlength=\"12\" placeholder=\"PSEUDO\">\n        </label>\n        <div id=\"roomRow\" class=\"room-row\">\n          <label class=\"field field--grow\">\n            <span class=\"field__label\">CODE SALLE</span>\n            <input id=\"roomInput\" maxlength=\"6\" placeholder=\"CODE SALLE\">\n          </label>\n          <button id=\"randomRoomBtn\" type=\"button\" class=\"btn btn--icon\" aria-label=\"Code aléatoire\">🎲</button>\n        </div>\n        <button id=\"joinBtn\" type=\"button\" class=\"btn btn--primary\">REJOINDRE</button>\n        <span id=\"mpNote\" class=\"mp-note\">Donne ce code à tes amis pour jouer dans la même salle (même niveau choisi ci-dessus). Synchronisation légère (pas temps réel), coop contre les mêmes dinosaures.</span>\n      </div>\n    </div>\n\n    <div class=\"post-game\">\n      <button id=\"restartBtn\" class=\"hidden btn btn--primary btn--large\">JOUER</button>\n      <button id=\"menuBtn\" class=\"hidden btn btn--text\">Choisir un autre niveau</button>\n    </div>\n  </div>\n</div>\n\n<script>\n(function(){\n  const canvas = document.getElementById('game');\n  const ctx = canvas.getContext('2d');\n  const overlay = document.getElementById('overlay');\n  const ovTitle = document.getElementById('ovTitle');\n  const ovText = document.getElementById('ovText');\n  const modeSelect = document.getElementById('modeSelect');\n  const profileStatsEl = document.getElementById('profileStats');\n  const levelBtns = Array.from(document.querySelectorAll('.levelBtn'));\n  const soloBtn = document.getElementById('soloBtn');\n  const onlineBtn = document.getElementById('onlineBtn');\n  const onlineForm = document.getElementById('onlineForm');\n  const nickInput = document.getElementById('nickInput');\n  const roomInput = document.getElementById('roomInput');\n  const randomRoomBtn = document.getElementById('randomRoomBtn');\n  const joinBtn = document.getElementById('joinBtn');\n  const restartBtn = document.getElementById('restartBtn');\n  const menuBtn = document.getElementById('menuBtn');\n  const mpStatusEl = document.getElementById('mpStatus');\n  const mpNoteEl = document.getElementById('mpNote');\n  const mpUnavailableMsgEl = document.getElementById('mpUnavailableMsg');\n  const healthBar = document.getElementById('healthBar');\n  const weaponLabelEl = document.getElementById('weaponLabel');\n  const damageFlashEl = document.getElementById('damageFlash');\n  const lowHealthVignetteEl = document.getElementById('lowHealthVignette');\n  const scoreEl = document.getElementById('score');\n  const enemiesLeftEl = document.getElementById('enemiesLeft');\n  const crosshair = document.getElementById('crosshair');\n\n  let W, H, focal;\n  const PLANE_LEN = 0.72; // FOV horizontal ~72°, plus confortable en écran étroit (portrait)\n  function resize(){\n    W = canvas.width = window.innerWidth;\n    H = canvas.height = window.innerHeight;\n    focal = (W/2) / PLANE_LEN; // focale indépendante de la hauteur -> plus de distorsion en portrait\n  }\n  window.addEventListener('resize', resize);\n  resize();\n\n  // ---------- NIVEAUX ----------\n  const LEVELS = [\n    {\n      name: 'Couloirs', size: 13, enemyCount: 7,\n      enemyHp: 60, enemySpeed: 1.1, enemyDmg: 12, weaponChance: 0.30,\n      wallA: [120, 55, 40], wallB: [104, 50, 38],\n      sky: ['#2a1810', '#1a1008'], floor: '#0f0c08', flicker: false\n    },\n    {\n      name: 'Grotte', size: 15, enemyCount: 9,\n      enemyHp: 70, enemySpeed: 1.3, enemyDmg: 15, weaponChance: 0.20,\n      wallA: [96, 90, 86], wallB: [66, 62, 60],\n      sky: ['#141414', '#0a0a0a'], floor: '#0e0c0a', flicker: true\n    },\n    {\n      name: 'Forêt', size: 17, enemyCount: 11,\n      enemyHp: 80, enemySpeed: 1.55, enemyDmg: 18, weaponChance: 0.10,\n      wallA: [56, 82, 40], wallB: [92, 66, 34],\n      sky: ['#0e1f0c', '#081a08'], floor: '#0c1408', flicker: false\n    },\n    // ---- Niveaux 4-6 : suite directe de la progression, +10% composés à partir\n    // des vraies valeurs de la Forêt (niveau 3 : enemyCount 11, enemyHp 80,\n    // enemySpeed 1.55, enemyDmg 18). Chaque palier = palier précédent x1.10.\n    // weaponChance continue de baisser et reste toujours < 15% (règle demandée).\n    {\n      // Désert (x1.10 vs Forêt : 11->12, 80->88, 1.55->1.71, 18->20)\n      name: 'Désert', size: 19, enemyCount: 12,\n      enemyHp: 88, enemySpeed: 1.71, enemyDmg: 20, weaponChance: 0.08,\n      wallA: [196, 164, 110], wallB: [150, 118, 74],\n      sky: ['#3c2712', '#1d1206'], floor: '#140d07', flicker: true // chaleur qui fait vibrer les murs\n    },\n    {\n      // Jungle tropicale (x1.21 vs Forêt : 11->13, 80->97, 1.55->1.88, 18->22)\n      name: 'Jungle tropicale', size: 21, enemyCount: 13,\n      enemyHp: 97, enemySpeed: 1.88, enemyDmg: 22, weaponChance: 0.06,\n      wallA: [46, 78, 42], wallB: [26, 52, 30],\n      sky: ['#0a170a', '#050d05'], floor: '#050f06', flicker: true // lumière filtrée par la canopée\n    },\n    {\n      // Lave (x1.331 vs Forêt : 11->15, 80->106, 1.55->2.06, 18->24) — niveau le plus dur\n      name: 'Lave', size: 23, enemyCount: 15,\n      enemyHp: 106, enemySpeed: 2.06, enemyDmg: 24, weaponChance: 0.05,\n      wallA: [132, 54, 26], wallB: [168, 74, 24],\n      sky: ['#2e0a02', '#160401'], floor: '#1c0703', flicker: true // pulsation de la lueur de lave\n    }\n  ];\n\n  // ---------- MAP ----------\n  let SIZE = LEVELS[0].size;\n  let MAP = null;\n  function generateMap(size){\n    const m = [];\n    for (let y = 0; y < size; y++){\n      const row = [];\n      for (let x = 0; x < size; x++){\n        if (x === 0 || y === 0 || x === size-1 || y === size-1) row.push(1);\n        else if (x % 2 === 0 && y % 2 === 0) row.push(1);\n        else row.push(0);\n      }\n      m.push(row);\n    }\n    return m;\n  }\n\n  function isWall(x, y){\n    const ix = Math.floor(x), iy = Math.floor(y);\n    if (ix < 0 || iy < 0 || ix >= SIZE || iy >= SIZE) return true;\n    return MAP[iy][ix] === 1;\n  }\n\n  // ---------- COLLISIONS / HITBOXES ----------\n  // Rayon de collision du joueur (murs + \"personal space\" face aux dinos)\n  const PLAYER_RADIUS = 0.22;\n  // Hurtbox : rayon \"réel\" du corps du dino utilisé pour juger si un tir touche.\n  // Plus petit que le sprite affiché -> on vise le corps, pas la boîte englobante entière.\n  const ENEMY_HURT_RADIUS = { trex: 0.34, carno: 0.27 };\n  // Hitbox physique (murs + collision avec le joueur), volontairement un peu plus\n  // grande que la hurtbox pour donner une sensation de \"masse\" cohérente.\n  const ENEMY_BODY_RADIUS = { trex: 0.5, carno: 0.4 };\n  // Marge de tolérance de visée ajoutée à la hurtbox (en unités monde) : évite\n  // une précision trop punitive sans transformer les tirs en aim-assist excessif.\n  const HIT_PADDING = 0.10;\n  // Petit espace laissé entre les corps pour éviter les collisions \"collantes\"\n  // quand un dino et le joueur se chevauchent.\n  const SEPARATION_PADDING = 0.03;\n  // Active/désactive l'affichage debug des hitboxes (touche H)\n  let debugHitboxes = false;\n\n  function pickOpenSpots(size, count, excluded){\n    const cells = [];\n    for (let y = 1; y < size-1; y++){\n      for (let x = 1; x < size-1; x++){\n        if (x % 2 === 0 && y % 2 === 0) continue; // pilier\n        if (Math.hypot(x-1, y-1) < 3.2) continue; // pas trop près du départ\n        if (excluded && excluded.has(x+','+y)) continue;\n        cells.push([x, y]);\n      }\n    }\n    for (let i = cells.length-1; i > 0; i--){\n      const j = Math.floor(Math.random()*(i+1));\n      [cells[i], cells[j]] = [cells[j], cells[i]];\n    }\n    return cells.slice(0, count);\n  }\n\n  // ---------- GAME STATE ----------\n  let player, enemies, pickups, score, running, zBuffer;\n  let currentLevel = 0;\n  let pendingLevel = 0;\n\n  function resetGame(levelIndex){\n    if (levelIndex !== undefined) currentLevel = levelIndex;\n    const cfg = LEVELS[currentLevel];\n    SIZE = cfg.size;\n    MAP = generateMap(SIZE);\n\n    player = {\n      x: 1.5, y: 1.5,\n      dirX: 1, dirY: 0,\n      planeX: 0, planeY: PLANE_LEN,\n      health: 100,\n      fireCooldown: 0,\n      weapon: 'pistol',\n      // vitesse courante (unités/s) et vitesse de rotation courante (rad/s),\n      // lissées progressivement vers la cible -> plus de à-coups au démarrage/arrêt\n      vx: 0, vy: 0, turnVel: 0,\n      // tangage (regard haut/bas), en pixels de décalage écran — remis à 0 à chaque partie\n      pitch: 0\n    };\n    const spots = pickOpenSpots(SIZE, cfg.enemyCount);\n    enemies = spots.map(([ex,ey], i) => ({\n      x: ex + 0.5, y: ey + 0.5,\n      hp: cfg.enemyHp, maxHp: cfg.enemyHp, alive: true,\n      type: i % 2 === 0 ? 'trex' : 'carno',\n      hue: Math.floor(Math.random()*360),\n      spriteSet: null,\n      hitFlash: 0,\n      transformX: 0, transformY: -1,\n      attackCooldown: 0,\n      // hurtRadius : rayon \"réel\" du dino utilisé pour la précision de visée (hurtbox)\n      // bodyRadius : rayon physique utilisé pour les collisions murs/joueur (un peu plus grand -> évite le clipping)\n      hurtRadius: ENEMY_HURT_RADIUS[i % 2 === 0 ? 'trex' : 'carno'],\n      bodyRadius: ENEMY_BODY_RADIUS[i % 2 === 0 ? 'trex' : 'carno']\n    }));\n\n    const usedKeys = new Set(spots.map(([x,y]) => x+','+y));\n    pickups = [];\n    for (const type of ['shotgun', 'sword']){\n      if (Math.random() < cfg.weaponChance){\n        const spot = pickOpenSpots(SIZE, 1, usedKeys)[0];\n        if (spot){\n          usedKeys.add(spot[0]+','+spot[1]);\n          pickups.push({ x: spot[0]+0.5, y: spot[1]+0.5, type, collected: false, transformX:0, transformY:-1 });\n        }\n      }\n    }\n\n    score = 0;\n    updateHUD();\n    updateWeaponUI();\n  }\n\n  function updateHUD(){\n    const pct = Math.max(0, player.health);\n    healthBar.style.width = pct + '%';\n    scoreEl.textContent = score;\n    enemiesLeftEl.textContent = enemies.filter(e => e.alive).length;\n    lowHealthVignetteEl.style.opacity = player.health < 35 ? String(Math.min(0.8, (35-player.health)/35*0.8)) : '0';\n    if (mp.enabled){\n      const count = Object.keys(mp.others).length + 1;\n      mpStatusEl.textContent = `🌐 ${mp.room} · ${LEVELS[mp.level].name} · ${count} joueur${count > 1 ? 's' : ''}`;\n    } else {\n      mpStatusEl.textContent = '';\n    }\n  }\n\n  let damageFlashTimer = null;\n  function flashDamage(){\n    damageFlashEl.classList.add('active');\n    clearTimeout(damageFlashTimer);\n    damageFlashTimer = setTimeout(() => damageFlashEl.classList.remove('active'), 90);\n  }\n\n  // ---------- ARMES ----------\n  const WEAPONS = {\n    pistol:  { label: '🔫 PISTOLET', fireLabel: 'TIRER', cooldown: 0.28, angleTol: 0.18, melee: false, dmg: () => 30 },\n    shotgun: { label: '💥 FUSIL À POMPE', fireLabel: 'TIRER', cooldown: 0.55, angleTol: 0.32, melee: false, dmg: (en) => Math.ceil(en.maxHp/2) + 2 },\n    sword:   { label: '🗡️ ÉPÉE', fireLabel: 'FRAPPER', cooldown: 0.38, angleTol: 0.55, melee: true, meleeRange: 1.3, dmg: (en) => en.maxHp + 5 }\n  };\n\n  function updateWeaponUI(){\n    const w = WEAPONS[player.weapon];\n    weaponLabelEl.textContent = w.label;\n    if (fireBtn) fireBtn.textContent = w.fireLabel;\n  }\n\n  // ---------- PROFIL JOUEUR (stats persistantes entre les sessions) ----------\n  const profileAvailable = typeof window.storage !== 'undefined' && typeof window.storage.get === 'function';\n  // cleared a une entrée par niveau (calculé sur LEVELS.length -> suit automatiquement\n  // tout ajout futur de niveaux, plus besoin de toucher ce fichier pour ça)\n  let profile = { totalKills: 0, totalGames: 0, bestScore: 0, cleared: new Array(LEVELS.length).fill(0) };\n\n  function renderProfileUI(){\n    const best = profile.cleared.reduce((a,b) => a+b, 0);\n    profileStatsEl.textContent = `🦖 ${profile.totalKills} dinosaures éliminés · 🏆 meilleur score ${profile.bestScore} · 🚪 ${best} niveaux réussis`;\n  }\n\n  function saveProfile(){\n    if (!profileAvailable) return;\n    try { window.storage.set('profile:stats', JSON.stringify(profile), false); } catch(e){}\n  }\n\n  async function loadProfile(){\n    renderProfileUI();\n    if (!profileAvailable){\n      profileStatsEl.textContent = 'Profil non disponible dans ce navigateur (ouvre le jeu depuis l\\'aperçu Claude).';\n      return;\n    }\n    try {\n      const res = await window.storage.get('profile:stats', false);\n      if (res && res.value){\n        const saved = JSON.parse(res.value);\n        profile = Object.assign(profile, saved);\n        // Migration douce : un ancien profil sauvegardé avec 3 niveaux (avant Désert/\n        // Jungle/Lave) garde sa progression existante, on complète juste les nouvelles\n        // entrées à 0 au lieu de tout réinitialiser.\n        if (!Array.isArray(profile.cleared)) profile.cleared = new Array(LEVELS.length).fill(0);\n        while (profile.cleared.length < LEVELS.length) profile.cleared.push(0);\n        if (profile.cleared.length > LEVELS.length) profile.cleared = profile.cleared.slice(0, LEVELS.length);\n      }\n    } catch(e){ /* premier lancement : pas encore de profil sauvegardé */ }\n    renderProfileUI();\n  }\n\n  // ---------- MULTIJOUEUR (via le stockage partagé de l'artefact) ----------\n  const mpAvailable = typeof window.storage !== 'undefined' && typeof window.storage.get === 'function';\n  const MP_PUSH_INTERVAL = 0.6;\n  const MP_PULL_INTERVAL = 1.4;\n  let mp = { enabled: false, room: null, level: 0, playerId: null, nick: '', others: {} };\n  let mpPushTimer = 0, mpPullTimer = 0;\n\n  function randomCode(len){\n    const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';\n    let s = '';\n    for (let i = 0; i < len; i++) s += chars[Math.floor(Math.random()*chars.length)];\n    return s;\n  }\n\n  async function mpJoin(room, nick, levelIndex){\n    mp.enabled = true;\n    mp.room = (room || '').toUpperCase().replace(/[^A-Z0-9]/g,'').slice(0,6) || 'GLOBAL';\n    mp.level = levelIndex;\n    mp.playerId = randomCode(8);\n    mp.nick = (nick || 'Joueur').trim().slice(0,12) || 'Joueur';\n    mp.others = {};\n    mpPushTimer = 0; mpPullTimer = 0;\n\n    try {\n      const res = await window.storage.get(`mp:${mp.room}:${mp.level}:enemies`, true);\n      if (res && res.value){\n        const remote = JSON.parse(res.value);\n        remote.forEach((r, i) => {\n          if (enemies[i]){ enemies[i].hp = Math.min(enemies[i].hp, r.hp); enemies[i].alive = enemies[i].alive && r.alive; }\n        });\n      }\n    } catch(e){ /* pas de salle existante, on en crée une nouvelle */ }\n    await mpPushEnemies();\n    await mpPushPlayer();\n  }\n\n  async function mpPushPlayer(){\n    if (!mp.enabled) return;\n    try {\n      const state = { nick: mp.nick, x: player.x, y: player.y, health: player.health, score, ts: Date.now() };\n      await window.storage.set(`mp:${mp.room}:${mp.level}:player:${mp.playerId}`, JSON.stringify(state), true);\n    } catch(e){}\n  }\n\n  async function mpPushEnemies(){\n    if (!mp.enabled) return;\n    try {\n      const local = enemies.map(e => ({ hp: e.hp, alive: e.alive }));\n      let merged = local;\n      const res = await window.storage.get(`mp:${mp.room}:${mp.level}:enemies`, true).catch(() => null);\n      if (res && res.value){\n        const remote = JSON.parse(res.value);\n        merged = local.map((l, i) => {\n          const r = remote[i] || l;\n          return { hp: Math.min(l.hp, r.hp), alive: l.alive && r.alive };\n        });\n        merged.forEach((m, i) => { if (enemies[i]){ enemies[i].hp = m.hp; enemies[i].alive = m.alive; } });\n      }\n      await window.storage.set(`mp:${mp.room}:${mp.level}:enemies`, JSON.stringify(merged), true);\n    } catch(e){}\n    updateHUD();\n  }\n\n  async function mpPullPlayers(){\n    if (!mp.enabled) return;\n    try {\n      const list = await window.storage.list(`mp:${mp.room}:${mp.level}:player:`, true);\n      if (!list || !list.keys) return;\n      const now = Date.now();\n      const seen = new Set();\n      for (const key of list.keys){\n        const id = key.split(':').pop();\n        if (id === mp.playerId) continue;\n        seen.add(id);\n        const res = await window.storage.get(key, true).catch(() => null);\n        if (!res || !res.value) continue;\n        const st = JSON.parse(res.value);\n        if (now - st.ts > 12000) continue;\n        const prev = mp.others[id];\n        mp.others[id] = {\n          nick: st.nick, health: st.health, score: st.score,\n          prevX: prev ? prev.dispX : st.x, prevY: prev ? prev.dispY : st.y,\n          dispX: st.x, dispY: st.y, updatedAt: now\n        };\n      }\n      for (const id of Object.keys(mp.others)) if (!seen.has(id)) delete mp.others[id];\n      updateHUD();\n    } catch(e){}\n  }\n\n  function mpLeave(){\n    if (!mp.enabled) return;\n    try { window.storage.delete(`mp:${mp.room}:${mp.level}:player:${mp.playerId}`, true); } catch(e){}\n  }\n  window.addEventListener('pagehide', mpLeave);\n\n  function renderOtherPlayers(){\n    const invDet = 1.0 / (player.planeX*player.dirY - player.dirX*player.planeY);\n    const horizon = H/2 + Math.round(player.pitch || 0); // même décalage de tangage que le reste du rendu\n    const now = Date.now();\n    const list = Object.values(mp.others).filter(o => o.health > 0).map(o => {\n      const t = Math.min(1, (now - o.updatedAt) / (MP_PULL_INTERVAL*1000));\n      const ix = o.prevX + (o.dispX - o.prevX) * t;\n      const iy = o.prevY + (o.dispY - o.prevY) * t;\n      const spriteX = ix - player.x, spriteY = iy - player.y;\n      const tX = invDet*(player.dirY*spriteX - player.dirX*spriteY);\n      const tY = invDet*(-player.planeY*spriteX + player.planeX*spriteY);\n      return { o, tX, tY };\n    }).filter(e => e.tY > 0.1).sort((a,b) => b.tY - a.tY);\n\n    for (const { o, tX, tY } of list){\n      const screenX = Math.floor((W/2) * (1 + tX/tY));\n      const col = Math.max(0, Math.min(W-1, screenX));\n      if (tY > zBuffer[col] + 0.15) continue;\n      const spriteH = Math.abs(Math.floor(focal / tY)) * 0.85;\n      const drawY = horizon - spriteH/2 + spriteH*0.12;\n      ctx.textAlign = 'center'; ctx.textBaseline = 'middle';\n      ctx.font = `${spriteH}px serif`;\n      ctx.fillText('🧍', screenX, drawY + spriteH/2);\n      ctx.fillStyle = '#8ecae6';\n      ctx.font = `${Math.max(11, spriteH*0.13)}px monospace`;\n      ctx.fillText(o.nick, screenX, drawY - spriteH*0.14);\n    }\n  }\n\n  // ---------- INPUT: CLAVIER + SOURIS (version PC) ----------\n  let hasFinePointer = false;\n  try {\n    hasFinePointer = !!(window.matchMedia && window.matchMedia('(any-pointer: fine)').matches);\n  } catch (e) { hasFinePointer = false; }\n  const isTouchDevice = (('ontouchstart' in window) || navigator.maxTouchPoints > 0) && !hasFinePointer;\n  const GAME_KEYS = ['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space','KeyW','KeyA','KeyS','KeyD'];\n  const keys = new Set();\n  window.addEventListener('keydown', (e) => {\n    const typingInField = e.target && (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA');\n\n    if (e.code === 'Escape'){\n      if (!onlineForm.classList.contains('hidden')){\n        onlineForm.classList.add('hidden');\n        mpUnavailableMsgEl.classList.add('hidden');\n      } else if (running){\n        pauseToMenu();\n      }\n      return;\n    }\n\n    if (typingInField) return; // laisse taper librement dans les champs pseudo / code salle\n\n    const playing = overlay.classList.contains('hidden');\n    if (playing && e.code === 'KeyH'){ debugHitboxes = !debugHitboxes; return; } // debug hitboxes\n    if (playing && GAME_KEYS.includes(e.code)) e.preventDefault();\n    if (playing){\n      keys.add(e.code);\n      if (e.code === 'Space') shoot();\n    }\n  });\n\n  // Partie mise en pause (Echap, ou perte du verrouillage souris) -> retour au\n  // menu, souris libérée pour qu'elle redevienne un curseur normal et cliquable.\n  function pauseToMenu(){\n    running = false;\n    mp.enabled = false;\n    releaseMouseLock();\n    ovTitle.textContent = 'DINO CORRIDOR';\n    ovText.textContent = 'Partie interrompue.';\n    modeSelect.classList.remove('hidden');\n    restartBtn.classList.add('hidden');\n    menuBtn.classList.add('hidden');\n    overlay.classList.remove('hidden');\n  }\n  window.addEventListener('keyup', (e) => keys.delete(e.code));\n\n  // ---------- SOURIS PC : visée façon FPS (Pointer Lock) ----------\n  // ANCIEN SYSTÈME (retiré) : il fallait cliquer-glisser sur le canvas pour\n  // tourner la caméra (mousedown -> accumulation du déplacement tant que le\n  // bouton restait enfoncé -> mouseup, et un clic sans glisser tirait). C'est\n  // ce qui donnait la sensation \"cliquer sur un côté de l'écran pour tourner\".\n  //\n  // NOUVEAU SYSTÈME : tant que le pointeur est verrouillé sur le canvas\n  // (Pointer Lock API), chaque mouvement de souris fait tourner la caméra en\n  // continu via event.movementX/Y, sans avoir à maintenir un clic. Le clic\n  // gauche ne sert plus qu'à tirer (ou à reprendre le verrouillage s'il a été\n  // perdu) : viser et tirer sont maintenant deux actions bien séparées.\n  // Sensibilité, facilement réglable :\n  const MOUSE_SENS_X = 0.0022; // rotation horizontale (rad par pixel de souris)\n  const MOUSE_SENS_Y = 0.9;    // décalage vertical du regard (px écran par pixel de souris)\n  const INVERT_Y = false;      // true = inverser l'axe vertical\n\n  const mouseLook = { dx: 0, dy: 0 };\n\n  function requestMouseLock(){\n    if (isTouchDevice) return; // jamais sur mobile/tactile : les sticks tactiles restent inchangés\n    if (canvas.requestPointerLock) canvas.requestPointerLock().catch(() => {});\n  }\n  function releaseMouseLock(){\n    if (document.pointerLockElement === canvas && document.exitPointerLock) document.exitPointerLock();\n  }\n\n  canvas.addEventListener('mousedown', (e) => {\n    if (isTouchDevice) return;\n    if (!overlay.classList.contains('hidden')) return; // dans les menus : clic normal sur les boutons, rien à faire ici\n    if (document.pointerLockElement !== canvas){\n      requestMouseLock(); // premier clic après une perte de focus : on ne fait que reprendre la visée, pas de tir surprise\n      return;\n    }\n    shoot();\n  });\n\n  // Pointer Lock donne des deltas relatifs (movementX/Y) indépendants de la\n  // position du curseur -> plus besoin de suivre une position ou un \"drag\".\n  document.addEventListener('mousemove', (e) => {\n    if (document.pointerLockElement !== canvas) return; // hors gameplay PC : souris = curseur classique\n    mouseLook.dx += e.movementX || 0;\n    mouseLook.dy += e.movementY || 0;\n  });\n\n  // Si le verrouillage se perd pendant une partie (Echap natif du navigateur,\n  // alt-tab, changement d'onglet...) on met le jeu en pause proprement, comme\n  // si le joueur avait appuyé sur Echap -> le curseur redevient utilisable.\n  document.addEventListener('pointerlockchange', () => {\n    if (document.pointerLockElement !== canvas && running && overlay.classList.contains('hidden')){\n      pauseToMenu();\n    }\n  });\n\n  // ---------- INPUT: DUAL STICKS ----------\n  function makeStick(baseX, baseY, radius){\n    const base = document.createElement('div');\n    base.className = 'stick-base';\n    base.style.width = base.style.height = (radius*2)+'px';\n    base.style.left = (baseX - radius)+'px';\n    base.style.top = (baseY - radius)+'px';\n    const nub = document.createElement('div');\n    nub.className = 'stick-nub';\n    const nubSize = radius*0.9;\n    nub.style.width = nub.style.height = nubSize+'px';\n    base.appendChild(nub);\n    document.body.appendChild(base);\n    return {\n      baseX, baseY, radius, nub, el: base,\n      touchId: null, dx: 0, dy: 0,\n      reposition(bx,by){ this.baseX=bx; this.baseY=by; base.style.left=(bx-radius)+'px'; base.style.top=(by-radius)+'px'; }\n    };\n  }\n\n  const STICK_R = 55;\n  let moveStick, lookStick, fireBtn;\n\n  function layoutControls(){\n    if (moveStick) moveStick.reposition(STICK_R + 24, H - STICK_R - 24);\n    if (lookStick) lookStick.reposition(W - STICK_R - 24, H - STICK_R - 24);\n    if (fireBtn){\n      fireBtn.style.width = fireBtn.style.height = '70px';\n      fireBtn.style.left = (W - STICK_R - 24 - 35) + 'px';\n      fireBtn.style.top = (H - STICK_R - 24 - STICK_R - 90) + 'px';\n    }\n  }\n\n  function setupControls(){\n    moveStick = makeStick(STICK_R + 24, H - STICK_R - 24, STICK_R);\n    lookStick = makeStick(W - STICK_R - 24, H - STICK_R - 24, STICK_R);\n\n    fireBtn = document.createElement('div');\n    fireBtn.id = 'fireBtn';\n    fireBtn.textContent = 'TIRER';\n    document.body.appendChild(fireBtn);\n    layoutControls();\n    window.addEventListener('resize', layoutControls);\n\n    if (!isTouchDevice){\n      moveStick.el.style.display = 'none';\n      lookStick.el.style.display = 'none';\n      fireBtn.style.display = 'none';\n      const hint = document.createElement('div');\n      hint.id = 'desktopHint';\n      hint.textContent = 'ZQSD/WASD/flèches : se déplacer · souris : viser (clic pour verrouiller le curseur) · clic gauche ou espace : tirer · Echap : pause';\n      document.body.appendChild(hint);\n    }\n\n    function updateNub(stick){\n      const len = Math.hypot(stick.dx, stick.dy);\n      const max = stick.radius * 0.9;\n      let nx = stick.dx, ny = stick.dy;\n      if (len > max){ nx = nx/len*max; ny = ny/len*max; }\n      stick.nub.style.transform = `translate(calc(-50% + ${nx}px), calc(-50% + ${ny}px))`;\n    }\n\n    function handleStart(e){\n      if (!overlay.classList.contains('hidden')) return; // laisse passer le tap sur les boutons de l'écran d'accueil\n      for (const t of e.changedTouches){\n        const x = t.clientX, y = t.clientY;\n        // fire button zone\n        const fRect = fireBtn.getBoundingClientRect();\n        const fcx = fRect.left + fRect.width/2, fcy = fRect.top + fRect.height/2;\n        if (Math.hypot(x-fcx, y-fcy) < fRect.width/2 + 10){\n          fireBtn.classList.add('pressed');\n          shoot();\n          continue;\n        }\n        if (x < W/2 && moveStick.touchId === null){\n          moveStick.touchId = t.identifier;\n          moveStick.dx = 0; moveStick.dy = 0;\n          updateNub(moveStick);\n        } else if (x >= W/2 && lookStick.touchId === null){\n          lookStick.touchId = t.identifier;\n          lookStick.dx = 0; lookStick.dy = 0;\n          updateNub(lookStick);\n        }\n      }\n      e.preventDefault();\n    }\n\n    function handleMove(e){\n      if (!overlay.classList.contains('hidden')) return;\n      for (const t of e.changedTouches){\n        if (t.identifier === moveStick.touchId){\n          moveStick.dx = t.clientX - moveStick.baseX;\n          moveStick.dy = t.clientY - moveStick.baseY;\n          updateNub(moveStick);\n        } else if (t.identifier === lookStick.touchId){\n          lookStick.dx = t.clientX - lookStick.baseX;\n          lookStick.dy = t.clientY - lookStick.baseY;\n          updateNub(lookStick);\n        }\n      }\n      e.preventDefault();\n    }\n\n    function handleEnd(e){\n      if (!overlay.classList.contains('hidden')) return;\n      for (const t of e.changedTouches){\n        if (t.identifier === moveStick.touchId){\n          moveStick.touchId = null; moveStick.dx = 0; moveStick.dy = 0;\n          updateNub(moveStick);\n        }\n        if (t.identifier === lookStick.touchId){\n          lookStick.touchId = null; lookStick.dx = 0; lookStick.dy = 0;\n          updateNub(lookStick);\n        }\n      }\n      fireBtn.classList.remove('pressed');\n      e.preventDefault();\n    }\n\n    window.addEventListener('touchstart', handleStart, {passive:false});\n    window.addEventListener('touchmove', handleMove, {passive:false});\n    window.addEventListener('touchend', handleEnd, {passive:false});\n    window.addEventListener('touchcancel', handleEnd, {passive:false});\n  }\n\n  // ---------- SHOOTING ----------\n  function shoot(){\n    if (!running) return;\n    if (player.fireCooldown > 0) return;\n    const w = WEAPONS[player.weapon];\n    player.fireCooldown = w.cooldown;\n\n    let bestDist = Infinity, target = null;\n    for (const en of enemies){\n      if (!en.alive) continue;\n      if (en.transformY <= 0.15) continue;\n      if (w.melee && en.transformY > w.meleeRange) continue;\n      // Hurtbox réelle : demi-largeur angulaire du corps du dino à cette distance,\n      // + marge de tolérance de visée, + latitude propre à l'arme (angleTol).\n      // Un dino lointain (petit à l'écran) a donc une hurtbox plus stricte qu'un\n      // dino proche : on vise le corps, pas une boîte englobante fixe et injuste.\n      const hurtHalfWidth = (en.hurtRadius + HIT_PADDING) / en.transformY;\n      const angleRatio = Math.abs(en.transformX / en.transformY);\n      if (angleRatio > hurtHalfWidth + w.angleTol) continue;\n      const col = Math.floor((W/2) * (1 + en.transformX/en.transformY));\n      const zb = zBuffer[Math.max(0, Math.min(W-1, col))];\n      if (en.transformY > zb + 0.1) continue;\n      if (en.transformY < bestDist){ bestDist = en.transformY; target = en; }\n    }\n    if (target){\n      target.hp -= w.dmg(target);\n      target.hitFlash = 0.15;\n      crosshair.classList.add('hit');\n      setTimeout(()=>crosshair.classList.remove('hit'), 100);\n      if (target.hp <= 0){\n        target.alive = false;\n        score += 100;\n        profile.totalKills++;\n        saveProfile();\n        if (mp.enabled) mpPushEnemies();\n      }\n      updateHUD();\n    }\n  }\n\n  // ---------- UPDATE ----------\n  const MOVE_SPEED = 2.4;\n  const TURN_SPEED = 2.6;\n  // Taux d'accélération / décélération (plus haut = plus réactif, plus bas = plus d'inertie).\n  // Deux taux distincts -> on démarre franchement mais on freine en douceur (pas d'arrêt sec).\n  const MOVE_ACCEL = 16;\n  const MOVE_DECEL = 11;\n  const TURN_ACCEL = 20;\n  const TURN_DECEL = 15;\n\n  // Lissage exponentiel indépendant du framerate (équivalent d'un \"smooth damp\").\n  // current -> target à une vitesse qui dépend de dt, jamais un saut instantané.\n  function approach(current, target, rate, dt){\n    const t = 1 - Math.exp(-rate * dt);\n    return current + (target - current) * t;\n  }\n\n  // Déplace une entité circulaire (joueur ou dino) en testant les murs séparément\n  // sur X et Y, avec un rayon de collision propre -> glisse le long des murs\n  // au lieu de se bloquer net, et n'ampute jamais le geste amorcé par le joueur.\n  function moveWithCollision(entity, nx, ny, radius){\n    if (!isWall(nx + (nx > entity.x ? radius : -radius), entity.y)) entity.x = nx;\n    if (!isWall(entity.x, ny + (ny > entity.y ? radius : -radius))) entity.y = ny;\n  }\n\n  function tryMove(nx, ny){\n    moveWithCollision(player, nx, ny, PLAYER_RADIUS);\n  }\n\n  function update(dt){\n    // Rotation venant du joystick tactile (mobile) : lissée via turnVel, comme\n    // avant -> pas d'à-coup au démarrage/relâchement du stick.\n    const lookLen = Math.hypot(lookStick.dx, lookStick.dy);\n    let turnInput = 0;\n    if (lookLen > 8) turnInput += (lookStick.dx / (lookStick.radius*0.9)) * TURN_SPEED;\n    const turnRate = Math.abs(turnInput) > Math.abs(player.turnVel) ? TURN_ACCEL : TURN_DECEL;\n    player.turnVel = approach(player.turnVel, turnInput, turnRate, dt);\n    let turn = player.turnVel * dt;\n\n    // Rotation venant de la souris PC (pointer lock) : appliquée en direct,\n    // SANS lissage. Un délai ici donnerait une sensation \"collante\"/en retard\n    // qui casserait la précision de visée attendue d'un FPS — chaque delta de\n    // souris représente déjà le mouvement réel de cette frame, peu importe dt.\n    turn += mouseLook.dx * MOUSE_SENS_X;\n\n    // Tangage (regard haut/bas) : uniquement piloté par la souris en pointer\n    // lock. Ce moteur (raycasting horizontal classique, à la Wolfenstein) n'a\n    // pas de vraie caméra 3D inclinable ; on simule le regard haut/bas en\n    // décalant verticalement le rendu (murs, sol/ciel, sprites), comme le\n    // faisaient les moteurs de l'époque. Purement visuel : ça ne touche ni la\n    // visée, ni les hitbox, ni les collisions, qui restent sur le plan horizontal.\n    if (document.pointerLockElement === canvas){\n      const dy = INVERT_Y ? mouseLook.dy : -mouseLook.dy;\n      player.pitch += dy * MOUSE_SENS_Y;\n      const maxPitch = H * 0.32;\n      player.pitch = Math.max(-maxPitch, Math.min(maxPitch, player.pitch));\n    }\n    mouseLook.dx = 0; mouseLook.dy = 0;\n\n    if (Math.abs(turn) > 1e-6){\n      const cosT = Math.cos(turn), sinT = Math.sin(turn);\n      const odx = player.dirX, opx = player.planeX;\n      player.dirX = player.dirX*cosT - player.dirY*sinT;\n      player.dirY = odx*sinT + player.dirY*cosT;\n      player.planeX = player.planeX*cosT - player.planeY*sinT;\n      player.planeY = opx*sinT + player.planeY*cosT;\n    }\n\n    // move (joystick tactile + clavier ZQSD/WASD/flèches)\n    const moveLen = Math.hypot(moveStick.dx, moveStick.dy);\n    let fwd = 0, strafe = 0;\n    if (moveLen > 8){\n      fwd += (-moveStick.dy / (moveStick.radius*0.9));\n      strafe += (moveStick.dx / (moveStick.radius*0.9));\n    }\n    if (keys.has('KeyW') || keys.has('ArrowUp')) fwd += 1;\n    if (keys.has('KeyS') || keys.has('ArrowDown')) fwd -= 1;\n    if (keys.has('KeyD') || keys.has('ArrowRight')) strafe += 1;\n    if (keys.has('KeyA') || keys.has('ArrowLeft')) strafe -= 1;\n    // Normalise la diagonale pour éviter d'aller plus vite en diagonale qu'en ligne droite\n    const inputLen = Math.hypot(fwd, strafe);\n    if (inputLen > 1){ fwd /= inputLen; strafe /= inputLen; }\n\n    // Vitesse cible en unités/s dans l'espace monde, puis lissage vers cette cible\n    const targetVX = (player.dirX*fwd + player.planeX*strafe*0.7) * MOVE_SPEED;\n    const targetVY = (player.dirY*fwd + player.planeY*strafe*0.7) * MOVE_SPEED;\n    const targetSpeed = Math.hypot(targetVX, targetVY);\n    const curSpeed = Math.hypot(player.vx, player.vy);\n    const moveRate = targetSpeed > curSpeed ? MOVE_ACCEL : MOVE_DECEL;\n    player.vx = approach(player.vx, targetVX, moveRate, dt);\n    player.vy = approach(player.vy, targetVY, moveRate, dt);\n\n    if (Math.hypot(player.vx, player.vy) > 0.001){\n      tryMove(player.x + player.vx*dt, player.y + player.vy*dt);\n    }\n\n    if (player.fireCooldown > 0) player.fireCooldown -= dt;\n\n    // ramassage des armes au sol\n    for (const p of pickups){\n      if (p.collected) continue;\n      if (Math.hypot(player.x - p.x, player.y - p.y) < 0.6){\n        p.collected = true;\n        player.weapon = p.type;\n        updateWeaponUI();\n      }\n    }\n\n    // enemies AI\n    const cfg = LEVELS[currentLevel];\n    let anyAlive = false;\n    for (const en of enemies){\n      if (!en.alive) continue;\n      anyAlive = true;\n      if (en.hitFlash > 0) en.hitFlash -= dt;\n\n      // Portée d'attaque = contact réel des deux hitboxes physiques (+ petite marge),\n      // au lieu d'une distance fixe arbitraire -> cohérent avec la taille de chaque dino.\n      const attackRange = en.bodyRadius + PLAYER_RADIUS + 0.05;\n      const ddx = player.x - en.x, ddy = player.y - en.y;\n      const dist = Math.hypot(ddx, ddy);\n\n      if (dist < 6.5 && dist > attackRange){\n        const spd = cfg.enemySpeed * dt;\n        moveWithCollision(en, en.x + (ddx/dist)*spd, en.y + (ddy/dist)*spd, en.bodyRadius);\n      } else if (dist <= attackRange){\n        if (en.attackCooldown <= 0){\n          player.health -= cfg.enemyDmg;\n          en.attackCooldown = 0.7;\n          flashDamage();\n          updateHUD();\n        }\n      }\n\n      // Anti-\"collant\" : si les hitboxes se chevauchent au-delà de la marge tolérée,\n      // on repousse doucement le dino pour qu'il ne s'enfonce jamais dans le joueur.\n      const minDist = en.bodyRadius + PLAYER_RADIUS - SEPARATION_PADDING;\n      if (dist > 0.0001 && dist < minDist){\n        const push = (minDist - dist);\n        moveWithCollision(en, en.x - (ddx/dist)*push, en.y - (ddy/dist)*push, en.bodyRadius);\n      }\n\n      if (en.attackCooldown > 0) en.attackCooldown -= dt;\n    }\n\n    // multijoueur : envoi/réception périodiques\n    if (mp.enabled){\n      mpPushTimer += dt; mpPullTimer += dt;\n      if (mpPushTimer >= MP_PUSH_INTERVAL){ mpPushTimer = 0; mpPushPlayer(); mpPushEnemies(); }\n      if (mpPullTimer >= MP_PULL_INTERVAL){ mpPullTimer = 0; mpPullPlayers(); }\n    }\n\n    if (player.health <= 0 && running){\n      running = false;\n      pendingLevel = currentLevel;\n      profile.bestScore = Math.max(profile.bestScore, score);\n      saveProfile(); renderProfileUI();\n      showOverlay('GAME OVER', `Les dinosaures ont gagné cette manche (${cfg.name}).`, 'REESSAYER');\n    } else if (!anyAlive && running){\n      running = false;\n      profile.bestScore = Math.max(profile.bestScore, score);\n      profile.cleared[currentLevel] = (profile.cleared[currentLevel] || 0) + 1;\n      saveProfile(); renderProfileUI();\n      if (currentLevel < LEVELS.length - 1){\n        pendingLevel = currentLevel + 1;\n        showOverlay('NIVEAU TERMINÉ', `${cfg.name} nettoyé ! Prêt pour ${LEVELS[currentLevel+1].name} ?`, 'NIVEAU SUIVANT');\n      } else {\n        pendingLevel = currentLevel;\n        showOverlay('VICTOIRE TOTALE', 'Les trois niveaux sont terminés. Bravo !', 'REJOUER');\n      }\n    }\n  }\n\n  // ---------- DINOSAURES : sprites d'apres les images fournies (recolores aleatoirement) ----------\n  const DINO_SCALE = 0.62;\n\n  const TREX_IMG_SRC = 'data:image/png;base64,';\n  const CARNO_IMG_SRC = 'data:image/png;base64,';\n\n  const dinoImages = { trex: new Image(), carno: new Image() };\n  dinoImages.trex.src = TREX_IMG_SRC;\n  dinoImages.carno.src = CARNO_IMG_SRC;\n\n  function tintCanvas(src, color){\n    const c = document.createElement('canvas');\n    c.width = src.width; c.height = src.height;\n    const cctx = c.getContext('2d');\n    cctx.drawImage(src, 0, 0);\n    cctx.globalCompositeOperation = 'source-atop';\n    cctx.fillStyle = color;\n    cctx.fillRect(0, 0, c.width, c.height);\n    return c;\n  }\n\n  function buildDinoCanvas(type, hue){\n    const img = dinoImages[type];\n    const c = document.createElement('canvas');\n    c.width = img.naturalWidth; c.height = img.naturalHeight;\n    const cctx = c.getContext('2d');\n    cctx.filter = `hue-rotate(${hue}deg) saturate(1.2)`;\n    cctx.drawImage(img, 0, 0);\n    cctx.filter = 'none';\n    return c;\n  }\n\n  function makeDinoSpriteSet(type, hue){\n    const base = buildDinoCanvas(type, hue);\n    return { base, hit: tintCanvas(base, '#ff5544') };\n  }\n\n  function drawDinoSprite(cx, groundY, h, en, phase){\n    const img = dinoImages[en.type];\n    if (!img.naturalWidth) return; // image pas encore decodee, on saute ce frame\n    if (!en.spriteSet) en.spriteSet = makeDinoSpriteSet(en.type, en.hue);\n    const spriteImg = en.hitFlash > 0 ? en.spriteSet.hit : en.spriteSet.base;\n    const bob = Math.sin(phase * Math.PI * 1.4) * h * 0.02;\n    const dh = h;\n    const dw = h * (spriteImg.width / spriteImg.height);\n    const dx = cx - dw/2;\n    const dy = groundY - dh + bob;\n\n    ctx.beginPath();\n    ctx.ellipse(cx, groundY, dw*0.32, dh*0.06, 0, 0, Math.PI*2);\n    ctx.fillStyle = 'rgba(0,0,0,0.35)';\n    ctx.fill();\n\n    ctx.imageSmoothingEnabled = false;\n    ctx.drawImage(spriteImg, dx, dy, dw, dh);\n  }\n\n  function drawPickup(cx, groundY, h, type){\n    const bob = Math.sin(Date.now()/260 + cx*0.05) * h*0.12;\n    const cy = groundY - h*0.5 + bob;\n    const glow = 0.5 + 0.5*Math.sin(Date.now()/220);\n\n    ctx.save();\n    const grad = ctx.createRadialGradient(cx, cy, 0, cx, cy, h*0.75);\n    const glowColor = type === 'sword' ? '227,220,170' : '255,150,90';\n    grad.addColorStop(0, `rgba(${glowColor},${0.45*glow})`);\n    grad.addColorStop(1, `rgba(${glowColor},0)`);\n    ctx.fillStyle = grad;\n    ctx.beginPath();\n    ctx.arc(cx, cy, h*0.75, 0, Math.PI*2);\n    ctx.fill();\n\n    ctx.translate(cx, cy);\n    ctx.lineJoin = 'round';\n    ctx.lineWidth = Math.max(1, h*0.06);\n    ctx.strokeStyle = '#161010';\n\n    if (type === 'shotgun'){\n      ctx.fillStyle = '#3a2414';\n      ctx.fillRect(-h*0.42, h*0.12, h*0.5, h*0.14);\n      ctx.strokeRect(-h*0.42, h*0.12, h*0.5, h*0.14);\n      ctx.fillStyle = '#2a2a2e';\n      ctx.fillRect(-h*0.05, -h*0.16, h*0.55, h*0.13);\n      ctx.fillRect(-h*0.05, -h*0.01, h*0.55, h*0.13);\n      ctx.strokeRect(-h*0.05, -h*0.16, h*0.55, h*0.13);\n      ctx.strokeRect(-h*0.05, -h*0.01, h*0.55, h*0.13);\n    } else {\n      ctx.fillStyle = '#cfd6dc';\n      ctx.beginPath();\n      ctx.moveTo(-h*0.06, h*0.28);\n      ctx.lineTo(h*0.06, h*0.28);\n      ctx.lineTo(h*0.05, -h*0.30);\n      ctx.lineTo(0, -h*0.42);\n      ctx.lineTo(-h*0.05, -h*0.30);\n      ctx.closePath();\n      ctx.fill(); ctx.stroke();\n      ctx.fillStyle = '#6b4a24';\n      ctx.fillRect(-h*0.16, h*0.28, h*0.32, h*0.07);\n      ctx.fillRect(-h*0.04, h*0.30, h*0.08, h*0.20);\n      ctx.strokeRect(-h*0.16, h*0.28, h*0.32, h*0.07);\n    }\n    ctx.restore();\n  }\n\n  // ---------- DEBUG : visualisation des hitboxes (touche H) ----------\n  // Vert = hurtbox (zone où le dino peut être touché par un tir)\n  // Orange = hitbox physique (collision joueur/murs + déclenchement de l'attaque du dino)\n  // Lignes jaunes = tolérance de visée de l'arme actuelle, au centre de l'écran\n  function drawDebugOverlay(){\n    ctx.save();\n    ctx.lineWidth = 2;\n    const horizon = H/2 + Math.round(player.pitch || 0);\n    for (const en of enemies){\n      if (!en.alive) continue;\n      if (en.transformY <= 0.1) continue;\n      const screenX = Math.floor((W/2) * (1 + en.transformX/en.transformY));\n      const col = Math.max(0, Math.min(W-1, screenX));\n      if (en.transformY > zBuffer[col] + 0.15) continue;\n\n      const spriteH = Math.min(Math.abs(focal / en.transformY) * DINO_SCALE, H*0.8);\n      const groundY = horizon + spriteH*0.35;\n      const midY = groundY - spriteH*0.5;\n\n      const hurtPx = Math.abs(focal / en.transformY) * en.hurtRadius;\n      ctx.strokeStyle = 'rgba(110,225,140,0.9)';\n      ctx.beginPath();\n      ctx.arc(screenX, midY, hurtPx, 0, Math.PI*2);\n      ctx.stroke();\n\n      const bodyPx = Math.abs(focal / en.transformY) * en.bodyRadius;\n      ctx.strokeStyle = 'rgba(224,89,47,0.9)';\n      ctx.beginPath();\n      ctx.ellipse(screenX, groundY, bodyPx, bodyPx*0.3, 0, 0, Math.PI*2);\n      ctx.stroke();\n\n      ctx.fillStyle = '#eae0cb';\n      ctx.font = '11px monospace';\n      ctx.textAlign = 'center';\n      ctx.fillText(`${Math.max(0, Math.ceil(en.hp))}hp · ${en.transformY.toFixed(1)}m`, screenX, groundY + 16);\n    }\n\n    const w = WEAPONS[player.weapon];\n    const coneW = (W/2) * w.angleTol;\n    ctx.strokeStyle = 'rgba(255,210,90,0.55)';\n    ctx.beginPath();\n    ctx.moveTo(W/2 - coneW, 0); ctx.lineTo(W/2 - coneW, H);\n    ctx.moveTo(W/2 + coneW, 0); ctx.lineTo(W/2 + coneW, H);\n    ctx.stroke();\n\n    ctx.fillStyle = 'rgba(255,210,90,0.9)';\n    ctx.font = '11px monospace';\n    ctx.textAlign = 'left';\n    ctx.fillText('DEBUG HITBOXES — touche H pour masquer', 10, H - 14);\n    ctx.restore();\n  }\n\n  // ---------- RENDER ----------\n  function render(){\n    const cfg = LEVELS[currentLevel];\n    focal = (W/2) / PLANE_LEN; // distance de projection réelle : évite les murs \"étirés\" en format portrait\n    // Ligne d'horizon décalée par le tangage souris (regard haut/bas) — voir\n    // update(dt) pour l'explication ; purement visuel, sans effet sur la visée.\n    const pitchPx = Math.round(player.pitch || 0);\n    const horizon = H/2 + pitchPx;\n\n    // sky / floor\n    const grad1 = ctx.createLinearGradient(0,0,0,horizon);\n    grad1.addColorStop(0, cfg.sky[0]);\n    grad1.addColorStop(1, cfg.sky[1]);\n    ctx.fillStyle = grad1;\n    ctx.fillRect(0,0,W,horizon);\n    ctx.fillStyle = cfg.floor;\n    ctx.fillRect(0,horizon,W,H-horizon);\n\n    zBuffer = new Array(W);\n\n    for (let x = 0; x < W; x++){\n      const cameraX = 2*x/W - 1;\n      const rayDirX = player.dirX + player.planeX*cameraX;\n      const rayDirY = player.dirY + player.planeY*cameraX;\n\n      let mapX = Math.floor(player.x), mapY = Math.floor(player.y);\n      const deltaDistX = rayDirX === 0 ? 1e30 : Math.abs(1/rayDirX);\n      const deltaDistY = rayDirY === 0 ? 1e30 : Math.abs(1/rayDirY);\n\n      let stepX, stepY, sideDistX, sideDistY;\n      if (rayDirX < 0){ stepX = -1; sideDistX = (player.x - mapX) * deltaDistX; }\n      else { stepX = 1; sideDistX = (mapX + 1 - player.x) * deltaDistX; }\n      if (rayDirY < 0){ stepY = -1; sideDistY = (player.y - mapY) * deltaDistY; }\n      else { stepY = 1; sideDistY = (mapY + 1 - player.y) * deltaDistY; }\n\n      let hit = 0, side = 0, safety = 0;\n      while (hit === 0 && safety < 64){\n        if (sideDistX < sideDistY){ sideDistX += deltaDistX; mapX += stepX; side = 0; }\n        else { sideDistY += deltaDistY; mapY += stepY; side = 1; }\n        if (mapX < 0 || mapY < 0 || mapX >= SIZE || mapY >= SIZE || MAP[mapY][mapX] === 1) hit = 1;\n        safety++;\n      }\n\n      let perpDist;\n      if (side === 0) perpDist = (mapX - player.x + (1-stepX)/2) / (rayDirX || 1e-9);\n      else perpDist = (mapY - player.y + (1-stepY)/2) / (rayDirY || 1e-9);\n      perpDist = Math.max(0.0001, Math.abs(perpDist));\n      zBuffer[x] = perpDist;\n\n      const lineHeight = Math.floor(focal / perpDist);\n      let drawStart = Math.floor(-lineHeight/2 + horizon);\n      let drawEnd = Math.floor(lineHeight/2 + horizon);\n\n      let shade = Math.max(0, 1 - perpDist/9);\n      if (cfg.flicker){\n        shade *= 0.9 + 0.1*Math.sin(Date.now()/280 + mapX*0.8 + mapY*0.6);\n      }\n      const base = ((mapX+mapY) % 2 === 0) ? cfg.wallA : cfg.wallB;\n      let r = base[0]*shade, g = base[1]*shade, b = base[2]*shade;\n      if (side === 1){ r *= 0.65; g *= 0.65; b *= 0.65; }\n      ctx.fillStyle = `rgb(${r|0},${g|0},${b|0})`;\n      ctx.fillRect(x, drawStart, 1, drawEnd - drawStart);\n    }\n\n    // sprites (ennemis + armes au sol, triés par profondeur)\n    const invDet = 1.0 / (player.planeX*player.dirY - player.dirX*player.planeY);\n    const sortedEnemies = enemies.filter(e => e.alive).map(en => {\n      const spriteX = en.x - player.x, spriteY = en.y - player.y;\n      en.transformX = invDet*(player.dirY*spriteX - player.dirX*spriteY);\n      en.transformY = invDet*(-player.planeY*spriteX + player.planeX*spriteY);\n      return { kind: 'dino', obj: en, depth: en.transformY };\n    });\n    const sortedPickups = pickups.filter(p => !p.collected).map(p => {\n      const spriteX = p.x - player.x, spriteY = p.y - player.y;\n      p.transformX = invDet*(player.dirY*spriteX - player.dirX*spriteY);\n      p.transformY = invDet*(-player.planeY*spriteX + player.planeX*spriteY);\n      return { kind: 'pickup', obj: p, depth: p.transformY };\n    });\n    const sorted = sortedEnemies.concat(sortedPickups).sort((a,b) => b.depth - a.depth);\n\n    for (const item of sorted){\n      const obj = item.obj;\n      if (obj.transformY <= 0.1) continue;\n      const screenX = Math.floor((W/2) * (1 + obj.transformX/obj.transformY));\n      const col = Math.max(0, Math.min(W-1, screenX));\n      if (obj.transformY > zBuffer[col] + 0.15) continue;\n\n      if (item.kind === 'dino'){\n        let spriteH = Math.abs(focal / obj.transformY) * DINO_SCALE;\n        spriteH = Math.min(spriteH, H * 0.8);\n        const groundY = horizon + spriteH*0.35;\n        const phase = Date.now()/220 + (obj.x*3 + obj.y*5);\n        drawDinoSprite(screenX, groundY, spriteH, obj, phase);\n      } else {\n        let spriteH = Math.abs(focal / obj.transformY) * 0.32;\n        spriteH = Math.min(spriteH, H * 0.35);\n        const groundY = horizon + spriteH*0.55;\n        drawPickup(screenX, groundY, spriteH, obj.type);\n      }\n    }\n\n    if (debugHitboxes) drawDebugOverlay();\n\n    // autres joueurs (multijoueur)\n    if (mp.enabled) renderOtherPlayers();\n\n    // weapon\n    const bobY = Math.sin(Date.now()/180) * 4;\n    ctx.save();\n    ctx.translate(W/2, H - 10 + bobY);\n    ctx.fillStyle = '#2b2b2b';\n    ctx.fillRect(-40, -70, 80, 90);\n    ctx.fillStyle = '#3d3d3d';\n    ctx.fillRect(-14, -140, 28, 80);\n    if (player.fireCooldown > 0.15){\n      ctx.fillStyle = 'rgba(255,210,90,0.9)';\n      ctx.beginPath();\n      ctx.moveTo(0, -150);\n      ctx.lineTo(-22, -110);\n      ctx.lineTo(22, -110);\n      ctx.closePath();\n      ctx.fill();\n    }\n    ctx.restore();\n  }\n\n  // ---------- MAIN LOOP ----------\n  let lastTime = 0;\n  function loop(ts){\n    if (!running) return;\n    const dt = Math.min(0.05, (ts - lastTime) / 1000 || 0);\n    lastTime = ts;\n    update(dt);\n    render();\n    requestAnimationFrame(loop);\n  }\n\n  function showOverlay(title, text, btnLabel){\n    releaseMouseLock(); // fin de partie/niveau : le curseur redevient utilisable pour cliquer sur les boutons\n    ovTitle.textContent = title;\n    ovText.textContent = text;\n    restartBtn.textContent = btnLabel;\n    modeSelect.classList.add('hidden');\n    restartBtn.classList.remove('hidden');\n    menuBtn.classList.remove('hidden');\n    overlay.classList.remove('hidden');\n  }\n\n  function beginGame(levelIndex){\n    resetGame(levelIndex);\n    profile.totalGames++;\n    saveProfile();\n    overlay.classList.add('hidden');\n    running = true;\n    lastTime = performance.now();\n    requestAnimationFrame(loop);\n    requestMouseLock(); // PC : (re)verrouille le curseur sur le canvas pour la visée FPS ; ignoré sur tactile\n    try {\n      if (screen.orientation && screen.orientation.lock) screen.orientation.lock('portrait').catch(() => {});\n    } catch(e){}\n  }\n\n  let selectedLevel = 0;\n  levelBtns.forEach(btn => {\n    btn.addEventListener('click', () => {\n      selectedLevel = parseInt(btn.dataset.level, 10);\n      levelBtns.forEach(b => b.classList.remove('selected'));\n      btn.classList.add('selected');\n    });\n  });\n\n  soloBtn.addEventListener('click', () => {\n    mp.enabled = false;\n    beginGame(selectedLevel);\n  });\n\n  if (!mpAvailable) onlineBtn.classList.add('disabled');\n  onlineBtn.addEventListener('click', () => {\n    if (!mpAvailable){\n      mpUnavailableMsgEl.classList.remove('hidden');\n      onlineForm.classList.add('hidden');\n      return;\n    }\n    mpUnavailableMsgEl.classList.add('hidden');\n    onlineForm.classList.remove('hidden');\n  });\n\n  randomRoomBtn.addEventListener('click', () => { roomInput.value = randomCode(4); });\n  roomInput.value = randomCode(4);\n\n  joinBtn.addEventListener('click', async () => {\n    joinBtn.disabled = true;\n    joinBtn.textContent = 'CONNEXION...';\n    await mpJoin(roomInput.value, nickInput.value, selectedLevel);\n    joinBtn.disabled = false;\n    joinBtn.textContent = 'REJOINDRE';\n    beginGame(selectedLevel);\n  });\n\n  restartBtn.addEventListener('click', () => {\n    beginGame(pendingLevel);\n    if (mp.enabled){\n      mp.level = pendingLevel;\n      mpPushEnemies(); // annonce un nouveau round frais à toute la salle (ce niveau)\n    }\n  });\n\n  menuBtn.addEventListener('click', () => {\n    running = false;\n    mp.enabled = false;\n    releaseMouseLock();\n    ovTitle.textContent = 'DINO CORRIDOR';\n    ovText.textContent = \"Des dinosaures rôdent dans les couloirs.\";\n    modeSelect.classList.remove('hidden');\n    restartBtn.classList.add('hidden');\n    menuBtn.classList.add('hidden');\n    overlay.classList.remove('hidden');\n  });\n\n  resetGame(0);\n  setupControls();\n  loadProfile();\n})();\n</script>\n</body>\n</html>\n";
